[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>RedRoom Fitness — The Best HIIT Workout in the World</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Oswald:wght@400;500;600;700&family=Inter:wght@300;400;500;600&display=swap" rel="stylesheet">
<style>
  *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

  :root {
    --red: #FF0000;
    --red-dark: #CC0000;
    --bg: #141414;
    --bg2: #1a1a1a;
    --bg3: #222;
    --white: #FFFFFF;
    --gray: #aaa;
    --gray-light: #ccc;
    --border: #333;
  }

  html { scroll-behavior: smooth; }

  body {
    background: var(--bg);
    color: var(--white);
    font-family: 'Inter', 'Helvetica Neue', sans-serif;
    font-size: 16px;
    line-height: 1.6;
    -webkit-font-smoothing: antialiased;
  }

  h1, h2, h3, h4, h5 {
    font-family: 'Oswald', sans-serif;
    text-transform: uppercase;
    letter-spacing: 0.04em;
    line-height: 1.1;
  }

  a { color: inherit; text-decoration: none; }

  img { display: block; width: 100%; }

  /* ── TOP PROMO BAR ── */
  .promo-bar {
    background: var(--red);
    color: var(--white);
    text-align: center;
    padding: 10px 20px;
    font-family: 'Oswald', sans-serif;
    font-size: 14px;
    letter-spacing: 0.06em;
    text-transform: uppercase;
  }
  .promo-bar a {
    color: var(--white);
    text-decoration: underline;
    margin-left: 10px;
    font-weight: 600;
  }

  /* ── NAVBAR ── */
  nav {
    position: sticky;
    top: 0;
    z-index: 100;
    background: rgba(20,20,20,0.97);
    backdrop-filter: blur(8px);
    border-bottom: 1px solid var(--border);
  }

  .nav-inner {
    max-width: 1400px;
    margin: 0 auto;
    padding: 0 24px;
    display: flex;
    align-items: center;
    justify-content: space-between;
    height: 68px;
    gap: 16px;
  }

  .nav-logo {
    font-family: 'Oswald', sans-serif;
    font-size: 26px;
    font-weight: 700;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    color: var(--white);
    flex-shrink: 0;
  }
  .nav-logo span { color: var(--red); }

  .nav-links {
    display: flex;
    align-items: center;
    gap: 28px;
    list-style: none;
  }

  .nav-links a {
    font-family: 'Oswald', sans-serif;
    font-size: 13px;
    font-weight: 500;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    color: var(--gray-light);
    transition: color 0.2s;
  }
  .nav-links a:hover, .nav-links a.active { color: var(--red); }

  .nav-actions {
    display: flex;
    align-items: center;
    gap: 10px;
    flex-shrink: 0;
  }

  .btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    font-family: 'Oswald', sans-serif;
    font-size: 13px;
    font-weight: 600;
    letter-spacing: 0.1em;
    text-transform: uppercase;
    padding: 10px 22px;
    border: none;
    cursor: pointer;
    transition: all 0.2s;
  }

  .btn-primary {
    background: var(--red);
    color: var(--white);
  }
  .btn-primary:hover { background: var(--red-dark); }

  .btn-outline {
    background: transparent;
    color: var(--white);
    border: 1px solid var(--border);
  }
  .btn-outline:hover { border-color: var(--white); }

  .btn-ghost {
    background: transparent;
    color: var(--gray-light);
    padding: 10px 14px;
    font-size: 12px;
  }
  .btn-ghost:hover { color: var(--white); }

  /* Hamburger */
  .nav-hamburger {
    display: none;
    flex-direction: column;
    gap: 5px;
    background: none;
    border: none;
    cursor: pointer;
    padding: 8px;
  }
  .nav-hamburger span {
    display: block;
    width: 24px;
    height: 2px;
    background: var(--white);
    transition: all 0.3s;
  }

  /* Mobile nav */
  .nav-mobile {
    display: none;
    background: var(--bg2);
    border-top: 1px solid var(--border);
    padding: 20px 24px;
  }
  .nav-mobile.open { display: block; }
  .nav-mobile a {
    display: block;
    font-family: 'Oswald', sans-serif;
    font-size: 18px;
    font-weight: 500;
    letter-spacing: 0.06em;
    text-transform: uppercase;
    color: var(--gray-light);
    padding: 10px 0;
    border-bottom: 1px solid var(--border);
    transition: color 0.2s;
  }
  .nav-mobile a:last-child { border-bottom: none; }
  .nav-mobile a:hover { color: var(--red); }

  /* ── SECTIONS ── */
  section { padding: 100px 24px; }

  .container {
    max-width: 1200px;
    margin: 0 auto;
  }

  .section-label {
    font-family: 'Oswald', sans-serif;
    font-size: 11px;
    font-weight: 600;
    letter-spacing: 0.18em;
    text-transform: uppercase;
    color: var(--red);
    margin-bottom: 16px;
  }

  /* ── HERO ── */
  .hero {
    position: relative;
    min-height: 92vh;
    display: flex;
    align-items: center;
    padding: 0 24px;
    overflow: hidden;
    background: linear-gradient(135deg, #0a0a0a 0%, #1a0000 40%, #141414 100%);
  }

  .hero-bg {
    position: absolute;
    inset: 0;
    background:
      radial-gradient(ellipse 80% 60% at 70% 50%, rgba(255,0,0,0.12) 0%, transparent 60%),
      radial-gradient(ellipse 40% 80% at 90% 20%, rgba(255,0,0,0.08) 0%, transparent 50%);
    pointer-events: none;
  }

  .hero-grid-lines {
    position: absolute;
    inset: 0;
    background-image:
      linear-gradient(rgba(255,0,0,0.04) 1px, transparent 1px),
      linear-gradient(90deg, rgba(255,0,0,0.04) 1px, transparent 1px);
    background-size: 60px 60px;
    pointer-events: none;
  }

  .hero-content {
    position: relative;
    z-index: 1;
    max-width: 1200px;
    margin: 0 auto;
    width: 100%;
    padding: 80px 0;
  }

  .hero-eyebrow {
    font-family: 'Oswald', sans-serif;
    font-size: 12px;
    font-weight: 600;
    letter-spacing: 0.24em;
    text-transform: uppercase;
    color: var(--red);
    margin-bottom: 24px;
    display: flex;
    align-items: center;
    gap: 12px;
  }
  .hero-eyebrow::before {
    content: '';
    display: block;
    width: 32px;
    height: 2px;
    background: var(--red);
  }

  .hero h1 {
    font-size: clamp(52px, 8vw, 110px);
    font-weight: 700;
    line-height: 0.95;
    margin-bottom: 36px;
    max-width: 900px;
  }

  .hero h1 em {
    font-style: normal;
    color: var(--red);
  }

  .hero-subtitle {
    font-size: 17px;
    color: var(--gray-light);
    max-width: 540px;
    margin-bottom: 48px;
    line-height: 1.7;
    font-weight: 400;
  }

  .hero-ctas {
    display: flex;
    gap: 16px;
    flex-wrap: wrap;
  }

  .btn-hero-primary {
    background: var(--red);
    color: var(--white);
    font-family: 'Oswald', sans-serif;
    font-size: 16px;
    font-weight: 600;
    letter-spacing: 0.14em;
    text-transform: uppercase;
    padding: 18px 48px;
    border: none;
    cursor: pointer;
    transition: all 0.2s;
    display: inline-flex;
    align-items: center;
    gap: 10px;
  }
  .btn-hero-primary:hover {
    background: var(--red-dark);
    transform: translateY(-1px);
  }

  .btn-hero-secondary {
    background: transparent;
    color: var(--white);
    font-family: 'Oswald', sans-serif;
    font-size: 16px;
    font-weight: 600;
    letter-spacing: 0.14em;
    text-transform: uppercase;
    padding: 18px 48px;
    border: 2px solid rgba(255,255,255,0.3);
    cursor: pointer;
    transition: all 0.2s;
    display: inline-flex;
    align-items: center;
  }
  .btn-hero-secondary:hover {
    border-color: var(--white);
    background: rgba(255,255,255,0.05);
  }

  .hero-stats {
    display: flex;
    gap: 48px;
    margin-top: 72px;
    padding-top: 48px;
    border-top: 1px solid var(--border);
  }

  .hero-stat-num {
    font-family: 'Oswald', sans-serif;
    font-size: 42px;
    font-weight: 700;
    color: var(--white);
    line-height: 1;
  }
  .hero-stat-num span { color: var(--red); }
  .hero-stat-label {
    font-size: 12px;
    letter-spacing: 0.1em;
    text-transform: uppercase;
    color: var(--gray);
    margin-top: 6px;
  }

  /* ── COMMUNITY PROMO ── */
  .community-promo {
    background: var(--bg2);
    border-top: 1px solid var(--border);
    border-bottom: 1px solid var(--border);
  }

  .community-inner {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 80px;
    align-items: center;
  }

  .community-text h2 {
    font-size: clamp(42px, 5vw, 72px);
    font-weight: 700;
    margin-bottom: 24px;
  }
  .community-text h2 span { color: var(--red); }

  .community-text p {
    font-size: 16px;
    line-height: 1.8;
    color: var(--gray-light);
    margin-bottom: 36px;
  }

  .community-visual {
    position: relative;
    height: 460px;
    background: linear-gradient(160deg, #1a0000, #0d0d0d);
    overflow: hidden;
    display: flex;
    align-items: center;
    justify-content: center;
  }

  .community-visual-inner {
    text-align: center;
    z-index: 1;
    position: relative;
  }

  .community-visual-glow {
    position: absolute;
    inset: 0;
    background: radial-gradient(ellipse 70% 70% at 50% 50%, rgba(255,0,0,0.18) 0%, transparent 70%);
  }

  .community-icon {
    font-size: 80px;
    margin-bottom: 16px;
    filter: drop-shadow(0 0 30px rgba(255,0,0,0.6));
  }

  .community-tagline {
    font-family: 'Oswald', sans-serif;
    font-size: 28px;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.06em;
    color: var(--red);
  }

  /* ── TWO WAYS ── */
  .two-ways { background: var(--bg); }

  .two-ways-heading {
    font-size: clamp(36px, 5vw, 64px);
    font-weight: 700;
    text-align: center;
    margin-bottom: 64px;
  }

  .two-ways-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 2px;
    background: var(--border);
  }

  .way-card {
    background: var(--bg2);
    padding: 64px 52px;
    position: relative;
    overflow: hidden;
    transition: background 0.3s;
  }
  .way-card:hover { background: #1e1e1e; }

  .way-card-accent {
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    height: 3px;
    background: var(--red);
  }

  .way-card-icon {
    font-size: 48px;
    margin-bottom: 24px;
  }

  .way-card h3 {
    font-size: 36px;
    font-weight: 700;
    margin-bottom: 8px;
    color: var(--red);
  }

  .way-card-subtitle {
    font-size: 14px;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    color: var(--gray);
    margin-bottom: 20px;
    font-family: 'Oswald', sans-serif;
  }

  .way-card p {
    font-size: 15px;
    line-height: 1.8;
    color: var(--gray-light);
    margin-bottom: 32px;
  }

  /* ── STUDIO EXPERIENCE ── */
  .studio-exp {
    background: linear-gradient(180deg, #0d0000 0%, #141414 100%);
    text-align: center;
    position: relative;
    overflow: hidden;
  }

  .studio-exp-glow {
    position: absolute;
    inset: 0;
    background: radial-gradient(ellipse 60% 50% at 50% 50%, rgba(255,0,0,0.1) 0%, transparent 70%);
    pointer-events: none;
  }

  .studio-exp .container { position: relative; z-index: 1; }

  .studio-exp h2 {
    font-size: clamp(38px, 5.5vw, 76px);
    font-weight: 700;
    margin-bottom: 28px;
  }
  .studio-exp h2 span { color: var(--red); }

  .studio-exp p {
    font-size: 17px;
    line-height: 1.8;
    color: var(--gray-light);
    max-width: 640px;
    margin: 0 auto 48px;
  }

  /* ── FREE TRIAL CTA ── */
  .free-trial {
    background: var(--red);
    padding: 80px 24px;
    text-align: center;
  }

  .free-trial h2 {
    font-size: clamp(36px, 5vw, 72px);
    font-weight: 700;
    color: var(--white);
    margin-bottom: 32px;
  }

  .btn-free-trial {
    display: inline-flex;
    align-items: center;
    font-family: 'Oswald', sans-serif;
    font-size: 18px;
    font-weight: 600;
    letter-spacing: 0.12em;
    text-transform: uppercase;
    padding: 20px 60px;
    background: var(--white);
    color: var(--red);
    border: none;
    cursor: pointer;
    transition: all 0.2s;
  }
  .btn-free-trial:hover {
    background: #f0f0f0;
    transform: translateY(-2px);
    box-shadow: 0 8px 30px rgba(0,0,0,0.3);
  }

  /* ── LIFESTYLE CAROUSEL ── */
  .carousel-section { background: var(--bg2); padding: 80px 0; }
  .carousel-section .container { padding: 0 24px; }

  .carousel-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    margin-bottom: 36px;
    padding: 0 24px;
  }

  .carousel-header h2 {
    font-size: 40px;
    font-weight: 700;
  }

  .carousel-controls {
    display: flex;
    gap: 12px;
  }

  .carousel-btn {
    width: 48px;
    height: 48px;
    background: var(--bg3);
    border: 1px solid var(--border);
    color: var(--white);
    font-size: 20px;
    cursor: pointer;
    display: flex;
    align-items: center;
    justify-content: center;
    transition: all 0.2s;
  }
  .carousel-btn:hover { background: var(--red); border-color: var(--red); }

  .carousel-track-wrapper {
    overflow: hidden;
    position: relative;
  }

  .carousel-track {
    display: flex;
    transition: transform 0.5s cubic-bezier(0.25, 0.46, 0.45, 0.94);
    will-change: transform;
  }

  .carousel-slide {
    min-width: calc(33.333% - 8px);
    margin-right: 12px;
    height: 340px;
    flex-shrink: 0;
    position: relative;
    overflow: hidden;
    cursor: grab;
  }
  .carousel-slide:active { cursor: grabbing; }

  .carousel-slide-inner {
    width: 100%;
    height: 100%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-family: 'Oswald', sans-serif;
    font-size: 22px;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    color: rgba(255,255,255,0.85);
    position: relative;
    z-index: 1;
    text-align: center;
    padding: 20px;
  }

  .slide-bg-1 { background: linear-gradient(135deg, #1a0000, #330000); }
  .slide-bg-2 { background: linear-gradient(135deg, #0d0d0d, #1a1a0a); }
  .slide-bg-3 { background: linear-gradient(135deg, #0a000d, #1a0a0d); }
  .slide-bg-4 { background: linear-gradient(135deg, #001a0a, #0d1a14); }
  .slide-bg-5 { background: linear-gradient(135deg, #1a0a00, #2a1200); }
  .slide-bg-6 { background: linear-gradient(135deg, #050015, #0a0020); }

  .slide-icon {
    font-size: 48px;
    margin-bottom: 16px;
    display: block;
    filter: drop-shadow(0 0 20px rgba(255,0,0,0.5));
  }

  .carousel-dots {
    display: flex;
    justify-content: center;
    gap: 8px;
    margin-top: 28px;
  }

  .carousel-dot {
    width: 8px;
    height: 8px;
    border-radius: 50%;
    background: var(--border);
    border: none;
    cursor: pointer;
    transition: all 0.2s;
  }
  .carousel-dot.active {
    background: var(--red);
    width: 24px;
    border-radius: 4px;
  }

  /* ── NEWSLETTER ── */
  .newsletter {
    background: var(--bg);
    border-top: 1px solid var(--border);
    border-bottom: 1px solid var(--border);
    padding: 80px 24px;
  }

  .newsletter-inner {
    max-width: 600px;
    margin: 0 auto;
    text-align: center;
  }

  .newsletter h2 {
    font-size: 36px;
    font-weight: 700;
    margin-bottom: 12px;
  }

  .newsletter p {
    font-size: 15px;
    color: var(--gray);
    margin-bottom: 36px;
    line-height: 1.7;
  }

  .newsletter-form {
    display: flex;
    gap: 0;
  }

  .newsletter-input {
    flex: 1;
    background: var(--bg3);
    border: 1px solid var(--border);
    border-right: none;
    color: var(--white);
    font-family: 'Inter', sans-serif;
    font-size: 15px;
    padding: 16px 20px;
    outline: none;
    transition: border-color 0.2s;
  }
  .newsletter-input::placeholder { color: var(--gray); }
  .newsletter-input:focus { border-color: var(--red); }
  .newsletter-input.error { border-color: #ff4444; }

  .newsletter-submit {
    background: var(--red);
    color: var(--white);
    font-family: 'Oswald', sans-serif;
    font-size: 14px;
    font-weight: 600;
    letter-spacing: 0.1em;
    text-transform: uppercase;
    padding: 16px 32px;
    border: none;
    cursor: pointer;
    transition: background 0.2s;
    white-space: nowrap;
  }
  .newsletter-submit:hover { background: var(--red-dark); }

  .newsletter-msg {
    margin-top: 12px;
    font-size: 13px;
    min-height: 20px;
    text-align: left;
  }
  .newsletter-msg.success { color: #4caf50; }
  .newsletter-msg.error { color: #ff4444; }

  /* ── FOOTER ── */
  footer {
    background: #0d0d0d;
    padding: 72px 24px 40px;
    border-top: 1px solid var(--border);
  }

  .footer-inner {
    max-width: 1200px;
    margin: 0 auto;
  }

  .footer-top {
    display: grid;
    grid-template-columns: 2fr 1fr 1fr 1fr;
    gap: 48px;
    margin-bottom: 64px;
  }

  .footer-brand .nav-logo {
    font-size: 30px;
    display: block;
    margin-bottom: 16px;
  }

  .footer-brand p {
    font-size: 13px;
    color: var(--gray);
    line-height: 1.7;
    max-width: 280px;
    margin-bottom: 24px;
  }

  .footer-col h4 {
    font-family: 'Oswald', sans-serif;
    font-size: 12px;
    font-weight: 600;
    letter-spacing: 0.16em;
    text-transform: uppercase;
    color: var(--white);
    margin-bottom: 20px;
  }

  .footer-col ul { list-style: none; }
  .footer-col ul li { margin-bottom: 10px; }
  .footer-col ul li a {
    font-size: 13px;
    color: var(--gray);
    transition: color 0.2s;
  }
  .footer-col ul li a:hover { color: var(--red); }

  .footer-bottom {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding-top: 32px;
    border-top: 1px solid var(--border);
    flex-wrap: wrap;
    gap: 16px;
  }

  .footer-copyright {
    font-size: 12px;
    color: var(--gray);
  }
  .footer-copyright span { color: var(--red); }

  .country-selector {
    position: relative;
  }

  .country-select-btn {
    background: var(--bg3);
    border: 1px solid var(--border);
    color: var(--gray-light);
    font-family: 'Inter', sans-serif;
    font-size: 12px;
    padding: 8px 14px;
    cursor: pointer;
    display: flex;
    align-items: center;
    gap: 8px;
    transition: all 0.2s;
  }
  .country-select-btn:hover { border-color: var(--red); color: var(--white); }

  .country-dropdown {
    display: none;
    position: absolute;
    bottom: calc(100% + 8px);
    right: 0;
    background: var(--bg2);
    border: 1px solid var(--border);
    min-width: 180px;
    z-index: 50;
    box-shadow: 0 -8px 32px rgba(0,0,0,0.5);
  }
  .country-dropdown.open { display: block; }
  .country-dropdown a {
    display: block;
    padding: 10px 16px;
    font-size: 13px;
    color: var(--gray-light);
    transition: all 0.15s;
  }
  .country-dropdown a:hover {
    background: var(--bg3);
    color: var(--red);
  }

  /* ── RESPONSIVE ── */
  @media (max-width: 1024px) {
    .community-inner { grid-template-columns: 1fr; gap: 40px; }
    .community-visual { height: 300px; }
    .footer-top { grid-template-columns: 1fr 1fr; gap: 36px; }
    .carousel-slide { min-width: calc(50% - 6px); }
  }

  @media (max-width: 768px) {
    section { padding: 64px 20px; }
    .nav-links, .nav-actions { display: none; }
    .nav-hamburger { display: flex; }
    .two-ways-grid { grid-template-columns: 1fr; }
    .hero-stats { gap: 28px; flex-wrap: wrap; }
    .hero-ctas { flex-direction: column; }
    .btn-hero-primary, .btn-hero-secondary { justify-content: center; }
    .footer-top { grid-template-columns: 1fr; gap: 32px; }
