(function() {
  const track = document.getElementById('carouselTrack');
  const wrapper = document.getElementById('carouselWrapper');
  const dotsContainer = document.getElementById('carouselDots');
  const prevBtn = document.getElementById('prevBtn');
  const nextBtn = document.getElementById('nextBtn');
  const slides = track.querySelectorAll('.carousel-slide');
  const totalSlides = slides.length;
  let current = 0;
  let slidesVisible = 3;
  let startX = 0;
  let isDragging = false;

  function getSlidesVisible() {
    if (window.innerWidth <= 768) return 1;
    if (window.innerWidth <= 1024) return 2;
    return 3;
  }

  function buildDots() {
    dotsContainer.innerHTML = '';
    const total = totalSlides - slidesVisible + 1;
    for (let i = 0; i < total; i++) {
      const dot = document.createElement('button');
      dot.className = 'carousel-dot' + (i === 0 ? ' active' : '');
      dot.setAttribute('aria-label', 'Go to slide ' + (i + 1));
      dot.addEventListener('click', () => goTo(i));
      dotsContainer.appendChild(dot);
    }
  }

  function updateDots() {
    const dots = dotsContainer.querySelectorAll('.carousel-dot');
    dots.forEach((d, i) => d.classList.toggle('active', i === current));
  }

  function getSlideWidth() {
    const slide = slides[0];
    return slide.getBoundingClientRect().width + 12;
  }

  function goTo(index) {
    slidesVisible = getSlidesVisible();
    const maxIndex = totalSlides - slidesVisible;
    current = Math.max(0, Math.min(index, maxIndex));
    track.style.transform = `translateX(-${current * getSlideWidth()}px)`;
    updateDots();
  }

  prevBtn.addEventListener('click', () => goTo(current - 1));
  nextBtn.addEventListener('click', () => goTo(current + 1));

  /* Swipe */
  wrapper.addEventListener('touchstart', e => { startX = e.touches[0].clientX; }, { passive: true });
  wrapper.addEventListener('touchend', e => {
    const diff = startX - e.changedTouches[0].clientX;
    if (Math.abs(diff) > 40) goTo(diff > 0 ? current + 1 : current - 1);
  });

  /* Mouse drag */
  wrapper.addEventListener('mousedown', e => { startX = e.clientX; isDragging = true; });
  wrapper.addEventListener('mousemove', e => { if (isDragging) e.preventDefault(); });
  wrapper.addEventListener('mouseup', e => {
    if (!isDragging) return;
    isDragging = false;
    const diff = startX - e.clientX;
    if (Math.abs(diff) > 40) goTo(diff > 0 ? current + 1 : current - 1);
  });
  wrapper.addEventListener('mouseleave', () => { isDragging = false; });

  window.addEventListener('resize', () => {
    slidesVisible = getSlidesVisible();
    buildDots();
    goTo(current);
  });

  slidesVisible = getSlidesVisible();
  buildDots();
  goTo(0);
})();

/* ── NEWSLETTER ── */
function handleNewsletter(e) {
  e.preventDefault();
  const input = document.getElementById('newsletterEmail');
  const msg = document.getElementById('newsletterMsg');
  const email = input.value.trim();
  const emailRe = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

  input.classList.remove('error');
  msg.className = 'newsletter-msg';

  if (!email) {
    input.classList.add('error');
    msg.className = 'newsletter-msg error';
    msg.textContent = 'Please enter your email address.';
    return;
  }
  if (!emailRe.test(email)) {
    input.classList.add('error');
    msg.className = 'newsletter-msg error';
    msg.textContent = 'Please enter a valid email address.';
    return;
  }
  msg.className = 'newsletter-msg success';
  msg.textContent = '✓ You\'re subscribed! Welcome to the Red Room.';
  input.value = '';
}

