  const email = input.value.trim();
  const emailRe = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  input.classList.remove('error');
  msg.className = 'newsletter-msg';
  if (!email) { input.classList.add('error'); msg.className = 'newsletter-msg error'; msg.textContent = 'Please enter your email address.'; return; }
  if (!emailRe.test(email)) { input.classList.add('error'); msg.className = 'newsletter-msg error'; msg.textContent = 'Please enter a valid email address.'; return; }
  msg.className = 'newsletter-msg success';
  msg.textContent = '✓ You\'re subscribed! Welcome to the Red Room.';
  input.value = '';
}
