<script>
/* Single-open accordion */
function toggleFaq(btn) {
  const item = btn.closest('.faq-item');
  const isOpen = item.classList.contains('open');

  // Close all
  document.querySelectorAll('.faq-item').forEach(i => {
    i.classList.remove('open');
    i.querySelector('.faq-question').setAttribute('aria-expanded', 'false');
    i.querySelector('.faq-answer').style.maxHeight = '0';
  });

  // Open clicked if it was closed
  if (!isOpen) {
    item.classList.add('open');
    btn.setAttribute('aria-expanded', 'true');
    const answer = item.querySelector('.faq-answer');
    answer.style.maxHeight = answer.scrollHeight + 'px';
  }
}

function handleNewsletter(e) {
  e.preventDefault();
  const input = document.getElementById('newsletterEmail');
  const msg = document.getElementById('newsletterMsg');
  const email = input.value.trim();
  const emailRe = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  input.classList.remove('error');
  msg.className = 'newsletter-msg';
  if (!email) { input.classList.add('error'); msg.className = 'newsletter-msg error'; msg.textContent = 'Please enter your email address.'; return; }
  if (!emailRe.test(email)) { input.classList.add('error'); msg.className = 'newsletter-msg error'; msg.textContent = 'Please enter a valid email address.'; return; }
  msg.className = 'newsletter-msg success';
  msg.textContent = '✓ You\'re subscribed! Welcome to the Red Room.';
  input.value = '';
}
